template <typename Char>
struct float_write_session {
  float_spec_view<Char> view;
  float_specs parsed;
  memory_buffer digits;

  explicit float_write_session(basic_format_specs<Char>& specs)
      : view{&specs}, parsed(parse_float_type_spec(specs)) {}
};

template <typename T, typename Char>
void prepare_float_session(float_write_session<Char>& session, T& value) {
  auto& fspecs = session.parsed;
  fspecs.sign = session.view.specs->sign;
  if (std::signbit(value)) {  // value < 0 is false for NaN so use signbit.
    fspecs.sign = sign::minus;
    value = -value;
  } else if (fspecs.sign == sign::minus) {
    fspecs.sign = sign::none;
  }
}

template <typename Char>
inline bool session_has_sign(const float_write_session<Char>& session) {
  return session.parsed.sign != sign::none;
}

template <typename Char>
inline sign_t session_sign(const float_write_session<Char>& session) {
  return session.parsed.sign;
}

template <typename Char>
inline void clear_session_sign(float_write_session<Char>& session) {
  session.parsed.sign = sign::none;
}

template <typename Char>
inline bool session_is_hex(const float_write_session<Char>& session) {
  return session.parsed.format == float_format::hex;
}

template <typename T, typename Char>
void append_hex_float(float_write_session<Char>& session, T value) {
  write_hex_float(session.digits, promote_float(value),
                  session.view.specs->precision, session.parsed);
}

template <typename Char>
inline string_view bytes_of(float_write_session<Char>& session) {
  return {session.digits.data(), session.digits.size()};
}

template <typename Char, typename OutputIt, typename T>
OutputIt write_decimal_float(OutputIt out, T value,
                             basic_format_specs<Char> specs, float_specs fspecs,
                             locale_ref loc, int precision) {
  memory_buffer buffer;
  if (fspecs.format == float_format::exp) {
    if (precision == max_value<int>())
      FMT_THROW(format_error("number is too big"));
    else
      ++precision;
  }
  if (const_check(std::is_same<T, float>())) fspecs.binary32 = true;
  fspecs.use_grisu = is_fast_float<T>();
  int exp = format_float(promote_float(value), precision, fspecs, buffer);
  fspecs.precision = precision;
  Char point =
      fspecs.locale ? decimal_point<Char>(loc) : static_cast<Char>('.');
  auto fp = big_decimal_fp{buffer.data(), static_cast<int>(buffer.size()), exp};
  return write_float(out, fp, specs, fspecs, point);
}

template <typename Char, typename OutputIt>
class padded_field_writer {
 private:
  OutputIt out_;
  locale_ref loc_;

 public:
  padded_field_writer(OutputIt out, locale_ref loc) : out_(out), loc_(loc) {}

  template <typename T>
  OutputIt write(T value, float_write_session<Char>& session) {
    if (const_check(!is_supported_floating_point(value))) return out_;
    auto& view = session.view;
    basic_format_specs<Char>* sp = view.specs;
    prepare_float_session(session, value);

    if (!std::isfinite(value)) {
      if (sp->fill.size() == 1 &&
          *sp->fill.data() == static_cast<Char>('0'))
        sp->fill[0] = static_cast<Char>(' ');
      return write_nonfinite(out_, std::isinf(value), *sp, session.parsed);
    }

    if (sp->align == align::numeric && session_has_sign(session)) {
      auto it = reserve(out_, 1);
      *it++ = static_cast<Char>(data::signs[session_sign(session)]);
      out_ = base_iterator(out_, it);
      clear_session_sign(session);
      if (sp->width != 0) --sp->width;
    }

    if (session_is_hex(session)) {
      append_hex_float(session, value);
      return write_bytes(out_, bytes_of(session), *sp);
    }
    int precision = sp->precision >= 0 || !sp->type ? sp->precision : 6;
    return write_decimal_float(out_, value, *sp, session.parsed, loc_,
                               precision);
  }
};

template <typename Char, typename OutputIt, typename T,
          FMT_ENABLE_IF(std::is_floating_point<T>::value)>
OutputIt write(OutputIt out, T value, basic_format_specs<Char> specs,
               locale_ref loc = {}) {
  float_write_session<Char> session(specs);
  return padded_field_writer<Char, OutputIt>(out, loc).write(value, session);
}

template <typename Char, typename OutputIt, typename T,
          FMT_ENABLE_IF(is_fast_float<T>::value)>
OutputIt write(OutputIt out, T value) {
  if (const_check(!is_supported_floating_point(value))) return out;

  using floaty = conditional_t<std::is_same<T, long double>::value, double, T>;
  using uint = typename dragonbox::float_info<floaty>::carrier_uint;
  auto bits = bit_cast<uint>(value);

  auto fspecs = float_specs();
  auto sign_bit = bits & (uint(1) << (num_bits<uint>() - 1));
  if (sign_bit != 0) {
    fspecs.sign = sign::minus;
    value = -value;
  }

  static const auto specs = basic_format_specs<Char>();
  uint mask = exponent_mask<floaty>();
  if ((bits & mask) == mask)
    return write_nonfinite(out, std::isinf(value), specs, fspecs);

  auto dec = dragonbox::to_decimal(static_cast<floaty>(value));
  return write_float(out, dec, specs, fspecs, static_cast<Char>('.'));
}

template <typename Char, typename OutputIt, typename T,
          FMT_ENABLE_IF(std::is_floating_point<T>::value &&
                        !is_fast_float<T>::value)>
inline OutputIt write(OutputIt out, T value) {
  return write(out, value, basic_format_specs<Char>());
}

